(()=>{const storage=localStorage,mode=storage.getItem('journey-mode')||'auto';document.documentElement.dataset.mode=mode==='auto'?'dark':mode;const storedLanguage=storage.getItem('journey-language');if(storedLanguage==='en'&&document.documentElement.lang==='zh-CN')location.replace('/goal-en.html');if(storedLanguage==='zh'&&document.documentElement.lang==='en')location.replace('/goal.html');document.getElementById('mode').onclick=()=>{const next=document.documentElement.dataset.mode==='dark'?'light':'dark';storage.setItem('journey-mode',next);document.documentElement.dataset.mode=next};document.getElementById('lang').onclick=e=>{e.preventDefault();storage.setItem('journey-language',document.documentElement.lang==='en'?'zh':'en');location.assign(e.currentTarget.href)}})();
